/*
 * glossary.js: every term the handbook defines, keyed by a stable id.
 *
 * Used by: the hover card on any `.term` / `dfn.term` element, the glossary
 * page, the search index, and the structure tests.
 *
 * Fields:
 *   term  display name
 *   aka   other names readers will meet in engines, docs or AI output
 *   def   one or two plain sentences; no term used here should need its own
 *         lookup to make sense
 *   ch    the chapter that teaches it ("4.2"). The tests use this to enforce
 *         "no term before its chapter": a page that mentions a term taught
 *         later must mark that mention data-forward.
 *
 * Keep ids lowercase-hyphenated; they are also the glossary page anchors.
 */
(function () {
  "use strict";

  var HB = (window.HB = window.HB || {});

  HB.glossary = {
    "actor": { term: "Actor", aka: ["AActor"], def: "Unreal Engine's object: anything that can be placed in a level. Its components give it meshes, collision, lights and behaviour, and its root component gives it a position.", ch: "2.3" },
    "additive-blending": { term: "Additive blending", aka: ["additive","add blend"], def: "Adding a new colour to the colour already in the image, so it can only brighten. Used for fire, sparks and glows; the result is the same in any draw order.", ch: "5.5" },
    "albedo": { term: "Albedo", aka: ["base colour","diffuse colour"], def: "The colour a surface reflects under white light, with no lighting or shadow baked in. Light-coloured surfaces bounce more light around a scene.", ch: "6.5" },
    "alpha": { term: "Alpha", aka: ["feature complete"], def: "The milestone at which every feature is in the game and playable from start to finish, after which no new features are started. Studios define the exact criteria differently.", ch: "1.1" },
    "alpha-blending": { term: "Alpha blending", aka: ["alpha blend","translucent","transparent","over"], def: "Mixing a new colour over the existing one in proportion to its alpha: alpha × new + (1 − alpha) × old. The result depends on draw order, so blended surfaces must be sorted back to front.", ch: "5.5" },
    "alpha-test": { term: "Alpha test", aka: ["alpha cutout","alpha clip","alpha clipping","alpha scissor","masked"], def: "Discarding pixels whose alpha falls below a threshold, typically 0.5, and drawing the rest fully opaque. Cut-outs such as leaves and fences can then write depth and need no sorting.", ch: "5.5" },
    "alpha-tested-foliage": { term: "Alpha-tested foliage", aka: ["cut-out foliage","masked foliage","alpha cards","foliage cards"], def: "Leaves and grass drawn as flat cards whose texture alpha cuts out the shape. The pixel shader must run across the whole card to decide what to keep, so dense foliage is costly to shade.", ch: "5.4" },
    "ambient-occlusion": { term: "Ambient occlusion", aka: ["AO"], def: "How much of the surrounding sky or environment a point can see. Creases, corners and contact points see less of it, so they receive less ambient light and look darker.", ch: "8.3" },
    "animation-system": { term: "Animation system", aka: ["animation","Animator","Animation Blueprint","AnimationTree"], def: "The engine system that plays, blends and adjusts animations, such as a character's walk and run cycles, and poses the skeleton every frame.", ch: "2.1" },
    "archetype": { term: "Archetype", aka: ["chunk"], def: "In an entity component system, the group of entities that have exactly the same component types. They are stored together in fixed-size blocks of memory called chunks.", ch: "2.3" },
    "art-director": { term: "Art director", aka: ["AD"], def: "The person who sets a game's visual direction and approves whether art, lighting and effects match it.", ch: "1.2" },
    "asset": { term: "Asset", aka: ["game asset","content"], def: "Any piece of content a game is built from, such as a model, texture, material, sound, animation or level, once the engine has imported it and can use it.", ch: "0.1" },
    "asset-cooking": { term: "Cooking", aka: ["cook","asset cooking","content build"], def: "Converting imported assets into the exact form one platform loads: textures compressed into that GPU's formats, shaders compiled, and anything the game never uses left out.", ch: "1.3" },
    "asset-database": { term: "Asset database", aka: ["asset registry","AssetDatabase","Asset Registry"], def: "The engine's record of every asset under a stable ID, with its type, location and dependencies, so references survive renames and moves.", ch: "1.3" },
    "asset-import": { term: "Import", aka: ["asset import","importer","reimport"], def: "The engine step that reads an exported file and converts it into the engine's own representation, using import settings stored alongside it.", ch: "1.3" },
    "asset-system": { term: "Asset system", aka: ["asset manager","resource manager","asset database"], def: "The engine system that finds, loads, tracks and unloads a game's content files, such as meshes, textures and sounds, so other systems can ask for them by name.", ch: "2.1" },
    "asset-validation": { term: "Asset validation", aka: ["data validation","asset checks","content validation"], def: "Automatic checks that every asset follows the project's rules, such as naming, triangle and texture-size budgets, and references only to files that exist.", ch: "1.3" },
    "astc": { term: "ASTC", aka: ["Adaptive Scalable Texture Compression","ASTC 4x4","ASTC 6x6","ASTC HDR"], def: "A texture format designed by Arm and AMD, used mainly on phones and Apple devices. Every block is 128 bits, but each texture picks a block size from 4 × 4 to 12 × 12 texels, from 8 down to 0.89 bits per pixel.", ch: "6.3" },
    "attribute-interpolation": { term: "Attribute interpolation", aka: ["interpolation","varying interpolation"], def: "Blending the values a vertex shader writes for a triangle's three corners, such as colour, UVs and normals, to get a value at each covered pixel.", ch: "5.3" },
    "audio-engine": { term: "Audio engine", aka: ["audio","sound system","audio middleware"], def: "The engine system that plays and mixes sounds, places them in 3D space relative to the listener, and streams music and dialogue.", ch: "2.1" },
    "backface-culling": { term: "Backface culling", aka: ["face culling"], def: "Skipping triangles that face away from the camera. The GPU decides which way a triangle faces from the order of its corners on screen.", ch: "4.4" },
    "bake-cage": { term: "Cage", aka: ["bake cage","projection cage","envelope","max ray distance"], def: "An inflated copy of the low-poly mesh that baking rays start from, travelling inwards to find the high-poly surface. Its distance decides which part of the sculpt each texel records.", ch: "6.4" },
    "baked-lighting": { term: "Baked lighting", aka: ["precomputed lighting","light baking"], def: "Lighting calculated ahead of time, usually in the editor, and stored in textures or probes. Cheap at runtime and high quality, but it cannot react to things that move.", ch: "8.2" },
    "baking": { term: "Baking", aka: ["texture baking","mesh map baking","normal map baking"], def: "Transferring detail into a texture ahead of time, most often from a high-poly sculpt onto a low-poly mesh as normal and ambient occlusion maps.", ch: "1.3" },
    "barycentric-coordinates": { term: "Barycentric coordinates", aka: ["barycentrics","barycentric weights"], def: "Three weights, one per corner of a triangle, that say how close a point is to each corner. They add up to 1, and a weight below 0 means the point is outside the triangle.", ch: "5.3" },
    "bc1": { term: "BC1", aka: ["DXT1"], def: "A block-compressed format storing RGB, with optional on-or-off alpha, at 4 bits per pixel: two endpoint colours and a 2-bit index per texel. Used for opaque colour and packed masks.", ch: "6.3" },
    "bc3": { term: "BC3", aka: ["DXT5"], def: "A block-compressed format at 8 bits per pixel: RGB stored as in BC1, plus a separately compressed alpha channel. Used for colour textures with smooth transparency.", ch: "6.3" },
    "bc4": { term: "BC4", aka: ["ATI1","RGTC1","R Compressed BC4"], def: "A single-channel block-compressed format at 4 bits per pixel, with eight levels between two endpoints in each block. Used for roughness, height and other single masks.", ch: "6.3" },
    "bc5": { term: "BC5", aka: ["ATI2","3Dc","RGTC2","RG Compressed BC5"], def: "A two-channel block-compressed format at 8 bits per pixel, each channel stored like BC4. The standard format for normal maps, which keep X and Y and rebuild Z in the shader.", ch: "6.3" },
    "bc6h": { term: "BC6H", aka: ["BC6","HDR Compressed"], def: "A block-compressed format for high dynamic range RGB at 8 bits per pixel, storing 16-bit floating-point colour. Used for skies, light probes and lightmaps instead of 64-bit float textures.", ch: "6.3" },
    "bc7": { term: "BC7", aka: ["BPTC"], def: "A high-quality block-compressed format for RGB or RGBA at 8 bits per pixel. Each 4 × 4 block picks one of eight modes, some with up to three pairs of endpoint colours.", ch: "6.3" },
    "bcn": { term: "BCn", aka: ["BC formats","block compression formats","DXTn","BPTC","RGTC"], def: "The family of block-compressed texture formats numbered BC1 to BC7, used on PCs and consoles. Each stores 4 × 4 texel blocks in 8 or 16 bytes and suits a different kind of data.", ch: "6.3" },
    "bent-normal": { term: "Bent normal", aka: [], def: "The average direction of open sky seen from a point. Where a surface is partly enclosed it leans away from the occluders, and engines use it to light and reflect more convincingly.", ch: "8.3" },
    "beta": { term: "Beta", aka: [], def: "The milestone at which a game is feature and content complete, and the remaining work is fixing bugs, optimising and polishing before release.", ch: "1.1" },
    "bilateral-filter": { term: "Bilateral filter", aka: ["depth-aware blur","edge-aware blur"], def: "A blur that only mixes neighbouring pixels at a similar depth and facing. It smooths noise without smearing one object's values onto another.", ch: "8.3" },
    "bit-depth": { term: "Bit depth", aka: ["8-bit","10-bit","bits per channel","bpc"], def: "How many bits store each colour channel. 8 bits give 256 levels per channel; 10 bits give 1,024, which HDR signals need to avoid visible steps.", ch: "3.2" },
    "bitangent": { term: "Bitangent", aka: ["binormal"], def: "The third direction of the tangent frame, along the texture's vertical axis and at right angles to the normal and tangent. It is usually rebuilt from the normal, the tangent and a stored sign rather than stored itself.", ch: "4.1" },
    "bits-per-pixel": { term: "Bits per pixel", aka: ["bpp","bits per texel","bpt","bit rate"], def: "How much memory a texture format uses per texel, on average: 32 for RGBA8, 8 for BC7, 4 for BC1. Multiply by width × height and divide by 8 to get bytes.", ch: "6.3" },
    "blend-mode": { term: "Blend mode", aka: ["blend state","blending mode","blend equation"], def: "The rule the GPU uses to combine a new colour with the colour already in the image: replace it, mix by alpha, add, multiply and so on. Engines expose it as a material setting.", ch: "5.5" },
    "block-compression": { term: "Block compression", aka: ["texture compression","GPU texture compression","DXT","S3TC"], def: "Storing a texture as small blocks of texels, usually 4 × 4, each in the same small number of bytes, so the GPU can find and decode any block directly while sampling. It cuts texture memory four to eight times for a small loss of quality.", ch: "6.3" },
    "blueprint": { term: "Blueprint", aka: ["Blueprint class","Blueprint Visual Scripting","BP"], def: "Unreal Engine's visual scripting system. A Blueprint class bundles an Actor's components, settings and node-based logic into an asset that can be placed many times, like a prefab.", ch: "2.3" },
    "build": { term: "Build", aka: ["game build","packaged build","package"], def: "A runnable copy of the game for one platform: compiled code plus cooked assets, packed into a few large files.", ch: "1.3" },
    "bump-mapping": { term: "Bump mapping", aka: ["bump map"], def: "Tilting the shading normal per pixel using the slopes of a height map, so a surface looks bumpy without changing shape. Introduced by James Blinn in 1978; normal maps are its modern form.", ch: "6.4" },
    "certification": { term: "Certification", aka: ["cert","submission","TRC","TCR","Xbox Requirements","XR","Lotcheck","VRC"], def: "The platform holder's testing of a submitted build against its published requirements before a game or update may be released. A failed build must be fixed and resubmitted.", ch: "1.4" },
    "channel-packing": { term: "Channel packing", aka: ["packed texture","ORM","mask map","texture packing"], def: "Storing several greyscale maps in the separate colour channels of one texture, such as ambient occlusion, roughness and metalness in red, green and blue. It saves texture reads and files.", ch: "6.3" },
    "clip-space": { term: "Clip space", aka: ["homogeneous clip space","clip coordinates","HClip"], def: "The four numbers (x, y, z, w) a vertex shader outputs for each vertex after the projection matrix. The GPU uses them to cut away anything outside the view before dividing by w.", ch: "3.4" },
    "colour-banding": { term: "Colour banding", aka: ["banding","contouring","posterisation"], def: "Visible stripes or steps in what should be a smooth gradient, such as a sky or fog, because too few levels are available to store it.", ch: "3.2" },
    "colour-channel": { term: "Colour channel", aka: ["channel","R, G, B, A","alpha channel"], def: "One of the separate numbers stored for each pixel, such as red, green, blue or alpha (opacity). Each channel is stored with a fixed number of bits.", ch: "3.2" },
    "colour-gamut": { term: "Colour gamut", aka: ["gamut","primaries","Rec. 2020","DCI-P3"], def: "The range of colours a colour space or display can produce, set by its red, green and blue primaries. Rec. 2020, used by HDR10, covers far more colours than sRGB.", ch: "3.2" },
    "command-buffer": { term: "Command buffer", aka: ["command list"], def: "A recorded list of GPU instructions, such as which settings to use, which buffers to read and what to draw. The CPU builds it, then hands it to the GPU in one go.", ch: "2.2" },
    "component": { term: "Component", aka: ["Actor Component","MonoBehaviour","fragment"], def: "A piece of data or behaviour attached to an object, such as a mesh, a collider, a light or a script. Objects are built by combining components.", ch: "2.3" },
    "compute-shader": { term: "Compute shader", aka: [], def: "A GPU program that is not tied to drawing triangles. Renderers use compute shaders for post effects, AO, culling and simulation.", ch: "5.6" },
    "compute-unit": { term: "Compute unit", aka: ["CU","SM","streaming multiprocessor","GPU core","shader core"], def: "The repeated building block of a GPU: a set of lanes with its own scheduler, registers, small cache and texture units. A GPU has anywhere from a handful to well over a hundred.", ch: "3.5" },
    "concept-phase": { term: "Concept phase", aka: ["concept","ideation"], def: "The first phase of a game project, where a few people define the idea, audience, platforms, scope and rough cost. It ends with a pitch and a decision on whether to fund pre-production.", ch: "1.1" },
    "constant-buffer": { term: "Constant buffer", aka: ["uniform buffer","cbuffer","UBO","uniforms"], def: "A small block of values the CPU sets for a draw, such as a material's tint or the camera's position, that stays the same for every vertex and pixel in that draw.", ch: "5.6" },
    "content-complete": { term: "Content complete", aka: ["asset complete"], def: "The point at which every level, asset, line of dialogue and piece of interface is in the game in final or near-final form, so only fixes and polish remain.", ch: "1.1" },
    "content-pipeline": { term: "Content pipeline", aka: ["asset pipeline","art pipeline"], def: "The chain of tools, rules and people that carries art from the programs artists make it in, through the engine, into the files that ship with the game.", ch: "1.3" },
    "continuous-integration": { term: "Continuous integration", aka: ["CI","build server","build farm"], def: "Build machines that pick up every submitted change, build and test it automatically, and report failures to the team.", ch: "1.3" },
    "cooked-asset": { term: "Cooked asset", aka: ["cooked content","runtime asset"], def: "An asset converted for one platform: compressed, resized and stripped of editor-only data. It loads fast and is not meant to be edited.", ch: "1.3" },
    "coordinate-space": { term: "Coordinate space", aka: ["space","coordinate system","coordinate frame","frame of reference"], def: "An origin plus a set of axes that positions are measured from. The same corner of a model has different numbers in each space.", ch: "3.4" },
    "cpu": { term: "CPU", aka: ["central processing unit","processor"], def: "The general-purpose processor that runs game logic and the engine, and prepares the work the GPU will do each frame.", ch: "3.5" },
    "cpu-cache": { term: "CPU cache", aka: ["cache line","cache miss"], def: "Small, fast memory beside each CPU core. Data arrives in blocks called cache lines, usually 64 bytes; needing data that is not there is a cache miss and can take around 200 times longer than a hit.", ch: "2.3" },
    "cross-compilation": { term: "Shader cross-compilation", aka: ["cross-compiling","DXC","SPIRV-Cross","shader translation"], def: "Compiling one shader source into the different formats each graphics API needs, such as DXIL for Direct3D 12, SPIR-V for Vulkan and a Metal library, so a team writes each shader once.", ch: "5.6" },
    "cross-product": { term: "Cross product", aka: ["vector product","cross"], def: "An operation on two 3D vectors that gives a third vector at right angles to both, as long as the area of the parallelogram they span. Swapping the two inputs makes it point the opposite way.", ch: "3.3" },
    "crunch": { term: "Crunch", aka: ["crunch time","crunch mode"], def: "Sustained long working hours used to hit a deadline. It raises output briefly, then costs mistakes, health and experienced people leaving.", ch: "1.1" },
    "custom-engine": { term: "Custom engine", aka: ["in-house engine","proprietary engine"], def: "An engine a studio builds and maintains for its own games, such as Guerrilla's Decima. It can fit the studio's needs exactly, but it needs a permanent team to keep it going.", ch: "2.4" },
    "day-one-patch": { term: "Day-one patch", aka: ["launch patch","day-zero patch"], def: "An update released on or before launch day that players download over the gold master. It carries fixes made after the release build was locked.", ch: "1.1" },
    "dcc-tool": { term: "DCC tool", aka: ["digital content creation tool","content creation software"], def: "A program artists make game content in, such as Blender, Maya, 3ds Max, Houdini, ZBrush or Substance 3D Painter. Each saves its own working file format.", ch: "1.3" },
    "deferred-rendering": { term: "Deferred rendering", aka: ["deferred shading"], def: "A way of organising a frame that first writes each pixel's surface properties to a G-buffer and lights them in a later pass. It handles many lights well.", ch: "7.3" },
    "delta-time": { term: "Delta time", aka: ["dt","variable timestep","DeltaSeconds","Time.deltaTime"], def: "The time that passed since the previous frame. Update code multiplies speeds by it so that objects move the same distance per second at any frame rate.", ch: "2.2" },
    "denoising": { term: "Denoising", aka: ["denoiser"], def: "Turning a noisy, under-sampled image into a clean one by blending neighbouring pixels and previous frames. Most real-time AO, GI and ray tracing depends on it.", ch: "8.7" },
    "depth-buffer": { term: "Depth buffer", aka: ["z-buffer","depth texture"], def: "A screen-sized image storing, for every pixel, how far the nearest visible surface is from the camera. It is the renderer's only record of the scene's shape after geometry is drawn.", ch: "5.5" },
    "depth-prepass": { term: "Depth pre-pass", aka: ["depth prepass","Z-prepass","early Z pass","depth priming"], def: "Drawing the opaque scene once with depth only, then again with full shading where each fragment must match the stored depth, so every visible pixel is shaded exactly once.", ch: "5.4" },
    "depth-test": { term: "Depth test", aka: ["z-test","ZTest","depth comparison"], def: "The GPU's per-pixel check that keeps a new fragment only if it is nearer than the distance already stored in the depth buffer. It is what lets solid objects be drawn in any order.", ch: "5.5" },
    "depth-write": { term: "Depth write", aka: ["z-write","ZWrite","depth draw mode"], def: "Storing a fragment's depth in the depth buffer after it passes the depth test. Opaque surfaces write depth; blended transparent surfaces usually test depth without writing it.", ch: "5.5" },
    "derived-data-cache": { term: "Derived data cache", aka: ["DDC","shared DDC","cache server","Unity Accelerator"], def: "A cache of processed versions of assets, such as compressed textures and compiled shaders, so work done once on one machine can be reused by the whole team.", ch: "1.3" },
    "detail-normal-map": { term: "Detail normal map", aka: ["detail map","detail normal","micro normal map"], def: "A small, tiling normal map of fine grain blended over a material's main normal map, adding close-up detail for almost no memory.", ch: "6.4" },
    "devkit": { term: "Devkit", aka: ["development kit","dev kit"], def: "A development version of a console or device, supplied by the platform holder under contract, that studios use to build, run and debug their game.", ch: "1.4" },
    "diffuse": { term: "Diffuse reflection", aka: ["diffuse"], def: "Light that a surface scatters evenly in all directions, so it looks the same from any viewing angle. Matte paint is mostly diffuse.", ch: "7.2" },
    "direct-light": { term: "Direct light", aka: ["direct lighting"], def: "Light that travels straight from a light source to a surface without bouncing off anything else first.", ch: "8.1" },
    "directx-12": { term: "DirectX 12", aka: ["Direct3D 12","D3D12","DX12"], def: "Microsoft's explicit graphics API for Windows and Xbox. The engine manages GPU memory and synchronisation itself, in exchange for much lower CPU overhead than older APIs.", ch: "3.5" },
    "discrete-gpu": { term: "Discrete GPU", aka: ["dedicated GPU","graphics card","dGPU"], def: "A GPU on its own card with its own VRAM, connected to the CPU through a PCI Express slot. Its VRAM is very fast, but data has to cross a much slower link to get there.", ch: "3.5" },
    "disocclusion": { term: "Disocclusion", aka: [], def: "Pixels that become visible this frame after being hidden last frame. Temporal techniques have no history for them, so they often show noise or ghosting there.", ch: "9.2" },
    "displacement": { term: "Displacement", aka: ["displacement mapping","vertex displacement","height displacement"], def: "Moving each vertex along its normal by an amount read from a height texture, so the surface's real shape and silhouette change. It needs enough vertices to carry the detail.", ch: "5.2" },
    "displacement-mapping": { term: "Displacement mapping", aka: ["displacement","vertex displacement","true displacement"], def: "Moving a mesh's real vertices along their normals by a height map, so the shape and its outline change. It needs enough vertices, often created by tessellation.", ch: "6.4" },
    "dithering": { term: "Dithering", aka: ["dither","debanding"], def: "Adding a tiny amount of noise before reducing an image to fewer levels, so hard steps become fine grain that the eye averages into a smooth gradient.", ch: "3.2" },
    "dot-product": { term: "Dot product", aka: ["scalar product","dot","N·L"], def: "Multiply two vectors' matching components and add the results. For unit vectors the answer is the cosine of the angle between them: 1 when they point the same way, 0 at right angles and -1 when they point opposite ways.", ch: "3.3" },
    "dots": { term: "DOTS", aka: ["Unity Entities","Data-Oriented Technology Stack"], def: "Unity's data-oriented toolset, built around the Entities package, its entity component system. GameObjects are converted into entities in the editor, a step Unity calls baking.", ch: "2.3" },
    "double-buffering": { term: "Double buffering", aka: ["front buffer","back buffer"], def: "Using two framebuffers: the display reads the front one while the GPU draws into the back one, then the two swap roles.", ch: "3.1" },
    "draw-call": { term: "Draw call", aka: ["draw","DrawIndexed"], def: "One instruction from the CPU telling the GPU to draw a set of triangles with a given mesh, material and settings. Each one has a CPU cost, so engines try to need fewer.", ch: "4.3" },
    "driver": { term: "Graphics driver", aka: ["driver","GPU driver","display driver"], def: "Software from the GPU maker that turns graphics API commands into instructions for one particular GPU and compiles shaders into its machine code.", ch: "3.5" },
    "dynamic-buffer": { term: "Dynamic buffer", aka: ["dynamic vertex buffer","streaming buffer"], def: "A GPU buffer the CPU rewrites often, sometimes every frame. Used for particles, UI and procedurally generated geometry.", ch: "4.2" },
    "early-z": { term: "Early-Z", aka: ["early depth test","early depth testing","early-Z rejection","Hi-Z"], def: "A depth test the GPU runs before the pixel shader, so fragments already hidden behind something drawn earlier are thrown away without being shaded.", ch: "5.4" },
    "ecs": { term: "Entity component system", aka: ["ECS","data-oriented design"], def: "A way to organise a game world as plain data: entities are ID numbers, components are data in tightly packed arrays, and systems are code that processes every entity with a given set of components.", ch: "2.3" },
    "ecs-system": { term: "System", aka: ["ECS system","processor"], def: "In an entity component system, code that runs over every entity with a particular set of components, for example moving everything that has a position and a velocity.", ch: "2.3" },
    "edge-aliasing": { term: "Edge aliasing", aka: ["jaggies","stair-stepping","geometric aliasing"], def: "Stair-step edges, broken-up thin objects and crawling pixels caused by testing coverage at only one point per pixel. Anti-aliasing techniques exist to reduce it.", ch: "5.3" },
    "editor": { term: "Editor", aka: ["level editor","authoring tools","Unreal Editor","Unity Editor"], def: "The engine's application for making a game: placing objects, importing content, tuning materials and testing. It stays on the team's machines and is not shipped to players.", ch: "2.1" },
    "engine-programmer": { term: "Engine programmer", aka: ["engine engineer","core programmer"], def: "A programmer who works on the engine's foundations, such as memory, threads, file loading, streaming and platform support, which every other system relies on.", ch: "1.2" },
    "entity": { term: "Entity", aka: [], def: "In an entity component system, an ID number that ties a set of components together. It has no data or behaviour of its own.", ch: "2.3" },
    "etc2": { term: "ETC2", aka: ["EAC","ETC2 RGB","ETC2 RGBA","ETC"], def: "A block-compressed texture format supported by every OpenGL ES 3.0 and Vulkan phone: 4 bits per pixel for RGB and 8 for RGBA. Its EAC variants store one or two channels.", ch: "6.3" },
    "far-plane": { term: "Far plane", aka: ["far clip plane","far clipping plane","zfar","draw distance"], def: "The distance beyond which the camera draws nothing. Some renderers place it at infinity.", ch: "3.4" },
    "fbx": { term: "FBX", aka: [".fbx"], def: "Autodesk's 3D exchange format for meshes, materials, skeletons, animation, cameras and lights. The file format is undocumented, so programs read and write it through Autodesk's SDK.", ch: "1.3" },
    "file-locking": { term: "File locking", aka: ["exclusive checkout","lock","Smart Locks","checkout"], def: "Letting only one person change a file at a time. Used for binary files such as models and textures, where two people's edits cannot be merged.", ch: "1.3" },
    "fill-rule": { term: "Fill rule", aka: ["top-left rule","rasterization rules"], def: "The rule that decides which triangle owns a pixel whose centre lies exactly on an edge two triangles share. Direct3D and OpenGL use the top-left rule, so every pixel along the edge is drawn exactly once.", ch: "5.3" },
    "fixed-function-stage": { term: "Fixed-function stage", aka: ["fixed function","fixed-function hardware"], def: "A pipeline stage built into the GPU as dedicated circuitry, such as the rasterizer or the depth test. It cannot be programmed, only configured with settings such as the cull mode or the blend mode.", ch: "5.1" },
    "fixed-hardware": { term: "Fixed hardware", aka: ["fixed platform","closed hardware"], def: "A platform where every player has the same machine, such as one console model, so a game can be tuned and tested for exactly that hardware.", ch: "1.4" },
    "fixed-timestep": { term: "Fixed timestep", aka: ["fixed update","physics tick","FixedUpdate()","_physics_process()"], def: "Advancing a simulation, usually physics, in steps of a constant length such as 1/60 of a second, whatever the frame rate. Each rendered frame runs zero, one or several steps to keep up with real time.", ch: "2.2" },
    "forward-rendering": { term: "Forward rendering", aka: ["forward shading"], def: "A way of organising a frame where each object is lit as it is drawn. Simple and good for transparency and mobile GPUs.", ch: "7.3" },
    "fov": { term: "Field of view", aka: ["FOV","view angle"], def: "How wide the camera sees, as an angle across either the height or the width of the screen. Engines differ on which of the two the number means.", ch: "3.4" },
    "fps": { term: "Frames per second", aka: ["fps","frame rate","framerate"], def: "How many finished images a game shows each second. At 60 fps a new image appears about every 16.7 milliseconds.", ch: "0.2" },
    "fragment": { term: "Fragment", aka: ["pixel candidate"], def: "One triangle's contribution to one pixel: the covered sample with its interpolated values, before the depth test and blending decide whether it becomes the pixel's colour.", ch: "5.4" },
    "frame": { term: "Frame", aka: [], def: "One complete image drawn by the game. At 60 frames per second each frame has about 16.7 milliseconds.", ch: "0.2" },
    "frame-budget": { term: "Frame budget", aka: ["budget"], def: "The time available to produce one frame at the target frame rate, split between systems: 16.7 ms at 60 fps, 11.1 ms at 90 fps, 33.3 ms at 30 fps.", ch: "11.1" },
    "frame-graph": { term: "Frame graph", aka: ["render graph","RDG","Render Dependency Graph"], def: "A description of a frame's passes and the render targets each reads and writes, from which the engine works out the order, skips unused passes, inserts synchronisation and reuses memory.", ch: "5.6" },
    "frame-latency": { term: "Frame latency", aka: ["input latency","input lag","input-to-photon latency","click-to-photon latency"], def: "The time from a player's input to the first image on screen that shows its effect. Every stage a frame passes through, and every frame it waits in a queue, adds to it.", ch: "2.2" },
    "frame-time": { term: "Frame time", aka: ["frametime","milliseconds per frame","delta time"], def: "How long one frame takes, in milliseconds: 1000 divided by the frame rate. Unlike frame rates, the times of separate pieces of work add up, so budgets are set in milliseconds.", ch: "0.2" },
    "framebuffer": { term: "Framebuffer", aka: ["frame buffer","colour buffer","render target"], def: "A block of GPU memory holding one whole image, one colour value per pixel. The display reads its picture from one framebuffer while the GPU draws the next frame into another.", ch: "3.1" },
    "frustum": { term: "View frustum", aka: ["frustum","camera frustum"], def: "The shape of the space a camera can see: a pyramid with its tip cut off, bounded by the near plane, the far plane and four sides set by the field of view.", ch: "3.4" },
    "g-buffer": { term: "G-buffer", aka: ["geometry buffer"], def: "A set of screen-sized images holding each pixel's surface data, such as colour, normal, roughness and depth, written before lighting in deferred rendering.", ch: "7.3" },
    "game-engine": { term: "Game engine", aka: ["engine"], def: "The reusable software a game is built on: runtime systems such as rendering, physics, animation and audio that run every frame, plus the editor and tools used to make the game's content.", ch: "2.1" },
    "game-loop": { term: "Game loop", aka: ["main loop","frame loop"], def: "The loop at the heart of every game that, once per frame, reads input, updates the game world, draws the new image and hands it to the display.", ch: "0.2" },
    "game-thread": { term: "Game thread", aka: ["main thread","GameThread"], def: "The CPU thread that runs the game loop: it reads input, runs gameplay code and updates the world. Most engines also call it the main thread.", ch: "2.2" },
    "gameobject": { term: "GameObject", aka: ["game object"], def: "Unity's object: a container for components that always has a Transform. Everything placed in a Unity scene is a GameObject.", ch: "2.3" },
    "gamma": { term: "Gamma", aka: ["gamma encoding","gamma correction","gamma space","transfer function"], def: "The curve that relates stored numbers to light output, close to light = value to the power 2.2. Values in gamma space look evenly spaced to the eye but give wrong results in lighting maths.", ch: "3.2" },
    "ghosting": { term: "Ghosting", aka: ["smearing","trails"], def: "Faint trails behind moving objects, left when a temporal technique blends in history from a place the object has already left.", ch: "9.2" },
    "git-lfs": { term: "Git LFS", aka: ["Git Large File Storage","LFS"], def: "An extension to Git that keeps large files on a separate server and only small pointer files in the repository. It can also lock files that cannot be merged.", ch: "1.3" },
    "global-illumination": { term: "Global illumination", aka: ["GI","indirect lighting"], def: "Lighting that includes light bouncing between surfaces, not only light arriving straight from sources.", ch: "8.1" },
    "glsl": { term: "GLSL", aka: ["OpenGL Shading Language","GLSL ES"], def: "The Khronos Group's C-like shader language for OpenGL, OpenGL ES and WebGL, also usable for Vulkan through SPIR-V. Godot's shading language is closely based on it.", ch: "5.6" },
    "gltf": { term: "glTF", aka: ["glTF 2.0","GL Transmission Format",".gltf",".glb"], def: "An open 3D delivery format from the Khronos Group, standardised as ISO/IEC 12113:2022. It stores meshes, PBR materials, skins and animation, with fixed units (metres) and Y as up.", ch: "1.3" },
    "godot": { term: "Godot", aka: ["Godot Engine","Godot 4","GDScript"], def: "A free, open-source engine under the MIT licence, scripted mainly in its own language, GDScript, with three renderers: Forward+, Mobile and Compatibility.", ch: "2.4" },
    "godot-node": { term: "Node", aka: ["Node3D","Node2D","Godot node"], def: "Godot's building block. Each node does one job, such as drawing a mesh or casting light, and a small tree of nodes makes an object.", ch: "2.3" },
    "gold-master": { term: "Gold master", aka: ["gold","going gold","release build"], def: "The final release build, approved by the platform holders and locked, that is used to manufacture discs and seed digital stores.", ch: "1.1" },
    "gpu": { term: "GPU", aka: ["graphics processing unit","graphics card"], def: "The graphics processor: thousands of simple cores running the same small program on many vertices or pixels at once.", ch: "3.5" },
    "gpu-queue": { term: "GPU queue", aka: ["command queue","render queue","frames in flight","submission"], def: "The line of submitted command buffers waiting for the GPU. The CPU submits a frame's work and moves on; the GPU runs it in order when it gets to it.", ch: "2.2" },
    "gpu-skinning": { term: "GPU skinning", aka: ["vertex shader skinning","compute skinning","skin cache"], def: "Bending an animated character's mesh on the GPU: each vertex is moved by a weighted blend of its bones' transforms, either in the vertex shader every time the mesh is drawn or once per frame in a compute shader whose result every pass reuses.", ch: "5.2" },
    "graphics-api": { term: "Graphics API", aka: ["API","rendering API"], def: "The published set of commands a program uses to drive a GPU, such as DirectX 12, Vulkan, Metal or WebGPU. Engines reach the GPU only through one.", ch: "3.5" },
    "graphics-pipeline": { term: "Graphics pipeline", aka: ["GPU pipeline","rendering pipeline","pipeline"], def: "The fixed sequence of stages a GPU puts every draw through: fetch the vertices, run the vertex shader, assemble triangles, find the pixels they cover, run the pixel shader, then test and blend the results into the image.", ch: "5.1" },
    "graphics-programmer": { term: "Graphics programmer", aka: ["rendering programmer","rendering engineer"], def: "A programmer who builds and optimises the renderer: lighting, shadows, the material system, post-processing and the code that drives the GPU. Graphics programmers also measure what each of those costs.", ch: "1.2" },
    "green-channel": { term: "Green channel convention", aka: ["OpenGL normal map","DirectX normal map","Y+","Y-","Flip Green Channel","Normal Map Invert Y"], def: "Which way green points in a normal map: up the texture in the OpenGL or Y+ convention, down in the DirectX or Y− convention. A map read with the wrong one makes bumps look like dents under vertical light.", ch: "6.4" },
    "gtao": { term: "GTAO", aka: ["ground-truth ambient occlusion","XeGTAO"], def: "A screen-space AO method that finds the two horizons in a few slices around each pixel and integrates the visible sky between them exactly, so it closely matches ray-traced AO for what the depth buffer shows.", ch: "8.3" },
    "handedness": { term: "Handedness", aka: ["left-handed","right-handed","chirality"], def: "Whether a coordinate system's x, y and z axes match the thumb, index and middle finger of a left hand or a right hand. With x to the right and y up, z points into the screen in a left-handed system and out of it in a right-handed one.", ch: "3.4" },
    "hard-soft-edges": { term: "Hard and soft edges", aka: ["smoothing groups","sharp edges","smoothing angle","auto smooth"], def: "A per-edge shading choice. Across a soft edge the normals are shared and shading blends smoothly; across a hard edge each side keeps its own normal and the edge shows as a crease.", ch: "4.1" },
    "hbao": { term: "HBAO", aka: ["horizon-based ambient occlusion","HBAO+"], def: "A screen-space AO method that marches outward from each pixel in a few directions and records how high the surrounding surfaces rise above it.", ch: "8.3" },
    "hdr-display": { term: "HDR display", aka: ["HDR output","display HDR","HDR screen"], def: "A screen and signal that can show far brighter highlights and deeper colours than a standard (SDR) screen. The game must send a different signal to use it.", ch: "3.2" },
    "hdr-rendering": { term: "HDR rendering", aka: ["scene-referred rendering","high dynamic range rendering","floating-point render target"], def: "Lighting a frame with floating-point values that can rise far above 1.0, as real light does, and converting to the display's range only at the end. It is separate from HDR output.", ch: "3.2" },
    "hdr10": { term: "HDR10", aka: ["PQ","SMPTE ST 2084","perceptual quantizer"], def: "The most common HDR signal: 10-bit values on the PQ curve (SMPTE ST 2084), which encodes absolute brightness up to 10,000 nits, with Rec. 2020 primaries and fixed metadata.", ch: "3.2" },
    "hdrp": { term: "HDRP", aka: ["High Definition Render Pipeline"], def: "Unity's render pipeline for high-fidelity rendering on desktop, Xbox and PlayStation, with physical light units and advanced materials. From 2026 it receives maintenance and no new features.", ch: "2.4" },
    "height-map": { term: "Height map", aka: ["heightmap","displacement map","depth map"], def: "A greyscale texture where brightness means height above the surface. Used to make normal maps, for parallax effects and to displace real geometry.", ch: "6.4" },
    "hitch": { term: "Hitch", aka: ["stutter","frame spike","spike"], def: "A frame, or a short run of frames, that takes far longer than the frames around it, so motion visibly freezes or jumps even when the average frame rate looks fine.", ch: "0.2" },
    "hlsl": { term: "HLSL", aka: ["High-Level Shader Language","High-Level Shading Language",".usf"], def: "Microsoft's C-like language for writing shaders, used by Direct3D and by Unreal and Unity for every platform. Compilers translate it to the formats other graphics APIs need.", ch: "5.6" },
    "horizon-angle": { term: "Horizon angle", aka: ["horizon"], def: "In one direction from a point, the steepest angle at which surrounding geometry rises above it. Everything below that angle is blocked; everything above is open sky.", ch: "8.3" },
    "immediate-mode-gpu": { term: "Immediate-mode GPU", aka: ["immediate-mode rendering","IMR"], def: "A GPU that draws triangles in the order they arrive and writes each pixel's colour and depth straight to full-screen buffers in memory. Desktop and console GPUs work this way.", ch: "3.5" },
    "index-buffer": { term: "Index buffer", aka: ["IBO","element buffer","element array"], def: "A GPU buffer listing which vertices form each triangle, by row number in the vertex buffer. It lets triangles share corners instead of storing them again.", ch: "4.2" },
    "index-format": { term: "Index format", aka: ["16-bit indices","32-bit indices","UInt16","UInt32"], def: "How many bytes each index uses. 16-bit indices are half the size but can only address 65,536 vertices; bigger meshes need 32-bit indices or splitting.", ch: "4.2" },
    "indirect-light": { term: "Indirect light", aka: ["bounce light","indirect lighting"], def: "Light that reaches a surface after bouncing off at least one other surface. It is why shadows are rarely pure black.", ch: "8.1" },
    "input-assembler": { term: "Input assembler", aka: ["input assembly","vertex fetch"], def: "The fixed GPU stage that reads the index buffer, fetches the vertex rows it points to and groups them into triangles for the vertex shader.", ch: "5.1" },
    "instance-override": { term: "Override", aka: ["instance override","prefab override"], def: "A value changed on one prefab instance only. It always wins over the prefab's own value, so later edits to that value on the prefab do not reach that instance.", ch: "2.3" },
    "instancing": { term: "GPU instancing", aka: ["instancing","instanced drawing"], def: "Drawing many copies of the same mesh in one draw call, each with its own position and small per-copy data.", ch: "4.3" },
    "interleaved": { term: "Interleaved layout", aka: ["array of structures","AoS"], def: "Storing all of a vertex's attributes next to each other in one row, then the next vertex's row, and so on.", ch: "4.2" },
    "internal-resolution": { term: "Internal resolution", aka: ["render resolution","half resolution"], def: "The resolution an effect or the whole frame is actually computed at, before being scaled to the output. Half resolution means a quarter of the pixels.", ch: "9.3" },
    "interpolator": { term: "Interpolator", aka: ["varying","varyings","vertex output","TEXCOORD","custom interpolator"], def: "A value the vertex shader outputs at each corner, such as a UV or a normal, which the GPU blends across the triangle so every pixel's shader receives its own in-between value.", ch: "5.2" },
    "job-system": { term: "Job system", aka: ["worker threads","task system","task graph","WorkerThreadPool"], def: "An engine service that splits work into small independent jobs and runs them on a pool of worker threads, about one per CPU core, so systems such as animation and physics can use every core.", ch: "2.2" },
    "lighting-artist": { term: "Lighting artist", aka: ["lighter"], def: "An artist who places and tunes lights, sky, fog and exposure in a level to create mood and make it readable, within the lighting budget.", ch: "1.2" },
    "lightmap": { term: "Lightmap", aka: [], def: "A texture holding precomputed lighting for static surfaces, laid out with its own UV coordinates.", ch: "8.2" },
    "linear-colour": { term: "Linear colour", aka: ["linear space","linear light","scene-linear"], def: "Colour values proportional to the amount of light, so twice the number means twice the light. Lighting, blending and blurring only give correct results on linear values.", ch: "3.2" },
    "live-ops": { term: "Live ops", aka: ["live operations","LiveOps","games as a service"], def: "The ongoing work of running a released game: hotfixes, scheduled patches, events, seasons and new content, each one built, tested and released like a small project.", ch: "1.1" },
    "local-transform": { term: "Local transform", aka: ["relative transform","localPosition","relative location"], def: "An object's position, rotation and scale measured from its parent. It stays the same when the parent moves.", ch: "2.3" },
    "lod": { term: "Level of detail", aka: ["LOD"], def: "Simpler versions of a mesh swapped in as it gets smaller on screen, so distant objects cost less to draw.", ch: "4.5" },
    "look-development": { term: "Look development", aka: ["look dev","lookdev"], def: "The work of finding and proving a game's visual style inside the engine, through target images, test scenes, materials and lighting, until the look can be repeated across the whole game.", ch: "1.1" },
    "lts": { term: "LTS", aka: ["long-term support"], def: "An engine release that keeps getting bug fixes for an extended period instead of new features. Teams in full production usually stay on one.", ch: "2.4" },
    "lumen": { term: "Lumen", aka: [], def: "Unreal Engine 5's real-time global illumination and reflection system. It computes bounced light, and short-range occlusion, without baking.", ch: "8.5" },
    "magnitude": { term: "Magnitude", aka: ["length","vector length","norm","size"], def: "The length of a vector, found with Pythagoras: the square root of the sum of its squared components. The vector (3, 4) has a magnitude of 5.", ch: "3.3" },
    "manifold": { term: "Manifold", aka: ["watertight","non-manifold","closed mesh"], def: "A mesh whose surface could be the skin of a real object, with every edge shared by at most two faces. Non-manifold geometry, such as three faces on one edge, confuses tools that need a clear inside and outside.", ch: "4.1" },
    "mass-entity": { term: "Mass Entity", aka: ["Mass","MassEntity","Mass AI"], def: "Unreal Engine's data-oriented framework for large numbers of similar things, such as crowds and traffic. Its components are called fragments and its systems processors.", ch: "2.3" },
    "matrix": { term: "Matrix", aka: ["matrices","4×4 matrix","transformation matrix","float4x4"], def: "A grid of numbers, usually 4 by 4 in graphics, that stores a transform. Multiplying a position by it applies the transform, and multiplying matrices together chains transforms into one.", ch: "3.4" },
    "memory-bandwidth": { term: "Memory bandwidth", aka: ["bandwidth","GB/s"], def: "How many bytes per second a memory can deliver to the processors reading it. Many rendering passes are limited by it more than by arithmetic, and on phones it costs battery and heat.", ch: "3.5" },
    "mesh": { term: "Mesh", aka: ["model","geometry"], def: "The shape of an object as a set of triangles joined at shared corners, plus the per-corner data needed to draw it.", ch: "4.1" },
    "mesh-shader": { term: "Mesh shader", aka: ["amplification shader","task shader","object shader","mesh shading"], def: "A newer kind of shader that replaces the input assembler and vertex shader. Each group of threads loads a small chunk of a mesh from any buffer and outputs a batch of triangles straight to the rasterizer, optionally after a task or amplification shader has culled whole chunks.", ch: "5.1" },
    "meshlet": { term: "Meshlet", aka: ["cluster"], def: "A small chunk of a mesh, typically 64 to 128 triangles, that modern renderers cull and process as a unit.", ch: "4.5" },
    "metal": { term: "Metal", aka: ["Metal 4"], def: "Apple's graphics API for Mac, iPhone, iPad and Vision Pro, and the only modern API native to them.", ch: "3.5" },
    "mikktspace": { term: "MikkTSpace", aka: ["Mikktspace","Calculate Mikktspace","synced tangent space"], def: "A standard way of computing a mesh's tangents, by Morten Mikkelsen, that gives the same result in every tool. When the baker and the engine both use it, baked normal maps decode without seams.", ch: "6.4" },
    "milestone": { term: "Milestone", aka: ["gate","milestone review"], def: "A dated checkpoint where the team delivers a build and evidence, and the people funding the game decide whether to continue. Its criteria should be agreed at the start of the phase it closes.", ch: "1.1" },
    "min-spec": { term: "Minimum specification", aka: ["min spec","minimum requirements","minimum system requirements"], def: "The least powerful hardware a PC game promises to run on, at its lowest settings. It should be a machine the team has actually tested.", ch: "1.4" },
    "mip-streaming": { term: "Mip streaming", aka: ["Mipmap Streaming","mipmap streaming","mip-level streaming"], def: "The common form of texture streaming: for each texture, keep in memory only the mip levels its nearest visible use needs, and load sharper levels from disk as the camera approaches.", ch: "6.3" },
    "model-matrix": { term: "Model matrix", aka: ["world matrix","object-to-world matrix","local-to-world matrix","M"], def: "The matrix that takes an object's vertices from object space into world space. It is built from the object's position, rotation and scale.", ch: "3.4" },
    "multi-bounce-ao": { term: "Multi-bounce AO", aka: ["multi-bounce approximation"], def: "A correction that brightens AO on light-coloured surfaces, because light bounces several times in a bright crease before it is absorbed.", ch: "8.3" },
    "mvp": { term: "MVP matrix", aka: ["model-view-projection","WorldViewProjection","WVP"], def: "The model, view and projection matrices multiplied into one, so a vertex shader can take a vertex from object space to clip space in a single multiply.", ch: "3.4" },
    "nanite": { term: "Nanite", aka: ["virtualized geometry"], def: "Unreal Engine 5's geometry system. It splits meshes into clusters and streams and draws only the detail each part of the screen needs.", ch: "4.5" },
    "ndc": { term: "Normalised device coordinates", aka: ["NDC","normalized device coordinates"], def: "Clip-space positions after the divide by w. Everything visible lies between -1 and 1 across and up, and inside a fixed depth range, whatever the size of the screen.", ch: "3.4" },
    "near-plane": { term: "Near plane", aka: ["near clip plane","near clipping plane","znear"], def: "The distance in front of the camera where drawing starts; anything closer is cut away. It has a large effect on depth precision, so it should be as far out as the game allows.", ch: "3.4" },
    "ngon": { term: "N-gon", aka: ["ngon","polygon"], def: "A face with more than four corners. Modelling tools allow them, but each tool may split them into triangles differently, so they often cause shading and baking surprises.", ch: "4.1" },
    "nit": { term: "Nit", aka: ["nits","cd/m²","candela per square metre"], def: "The unit of screen brightness: one candela per square metre. Standard screens show white at roughly 100 to 300 nits; HDR screens reach 400 to 1,000 nits or more in highlights.", ch: "3.2" },
    "noise": { term: "Sampling noise", aka: ["noise","grain"], def: "Random speckle in an effect that was computed from too few samples per pixel. More samples, or denoising, removes it.", ch: "8.7" },
    "normal": { term: "Normal", aka: ["surface normal","vertex normal"], def: "A direction pointing straight out of a surface. Lighting uses it to work out how directly light hits that point.", ch: "4.1" },
    "normal-map": { term: "Normal map", aka: ["normal texture","tangent-space normal map"], def: "A texture that stores a surface direction for every texel as red, green and blue. Lighting reads it per pixel, so flat triangles shade as if they had bumps, grooves and scratches.", ch: "6.4" },
    "object-space": { term: "Object space", aka: ["model space","local space","mesh space"], def: "Coordinates measured from a model's own origin, the way the artist built it. Vertex buffers store positions in object space.", ch: "3.4" },
    "object-space-normal-map": { term: "Object-space normal map", aka: ["object space normal map","model-space normal map","world-space normal map"], def: "A normal map whose directions are relative to the whole model rather than to the surface. It needs no tangents, but works only on the mesh it was made for and cannot tile, mirror or deform.", ch: "6.4" },
    "oit": { term: "Order-independent transparency", aka: ["OIT","per-pixel sorting","weighted blended OIT","depth peeling"], def: "Techniques that blend transparent layers correctly per pixel whatever order they are drawn in, either by storing and sorting every layer or by approximating the result in one pass.", ch: "5.5" },
    "open-source": { term: "Open source", aka: ["FOSS","MIT licence"], def: "Software whose source anyone may use, change and redistribute under a licence such as MIT. Godot is open source, and games made with it belong to their makers.", ch: "2.4" },
    "opengl": { term: "OpenGL", aka: ["OpenGL ES","GLES","WebGL","GL"], def: "The older cross-platform graphics API, with OpenGL ES on phones and WebGL in browsers as its cut-down relatives. Still widely supported, but replaced by Vulkan, Metal and DirectX 12 for new work on most platforms.", ch: "3.5" },
    "orthographic-projection": { term: "Orthographic projection", aka: ["orthographic","ortho","orthogonal","parallel projection"], def: "A projection in which lines of sight run parallel, so things keep their size at any distance. Used for 2D games, UI, top-down strategy views and directional-light shadows.", ch: "3.4" },
    "output-merger": { term: "Output merger", aka: ["ROP","render output unit","raster operations","OM"], def: "The fixed last stage of the pipeline. It tests each shaded pixel's depth against the depth buffer, then writes or blends its colour into the image being drawn. The hardware units that do this are often called ROPs.", ch: "5.1" },
    "overdraw": { term: "Overdraw", aka: ["overshading","overdraw count"], def: "Shading the same pixel more than once in a frame because several surfaces cover it. An average overdraw of 3 means three pixel shader runs for every pixel on screen.", ch: "5.4" },
    "parallax-mapping": { term: "Parallax mapping", aka: ["offset mapping","Bump Offset","virtual displacement mapping"], def: "Shifting each pixel's texture lookup by an amount taken from a height map and the viewing angle, so deep detail seems to move correctly with the camera. One extra texture read; it breaks down at grazing angles.", ch: "6.4" },
    "parallelism": { term: "Parallelism", aka: ["parallel processing","data parallelism"], def: "Doing many pieces of the same job at the same time instead of one after another. GPUs are built for it: thousands of lanes each work on their own vertex or pixel at once.", ch: "3.5" },
    "perforce": { term: "Perforce", aka: ["P4","Helix Core","p4"], def: "A version control system built for very large binary files and large teams, with file locking. Its server, long called Helix Core, is now named P4.", ch: "1.3" },
    "perspective-correct-interpolation": { term: "Perspective-correct interpolation", aka: ["perspective correction","affine interpolation","affine texture mapping"], def: "Blending vertex values so they follow the 3D surface rather than the flat screen, by dividing by depth before blending. Without it, called affine interpolation, textures bend and swim on surfaces that lean away from the camera.", ch: "5.3" },
    "perspective-divide": { term: "Perspective divide", aka: ["divide by w","homogeneous divide","w-divide"], def: "The step after the vertex shader where the GPU divides a clip-space position's x, y and z by its w. With a perspective projection w grows with distance, which is what makes far things smaller.", ch: "3.4" },
    "perspective-projection": { term: "Perspective projection", aka: ["perspective"], def: "A projection in which lines of sight meet at the camera, so distant things look smaller. The usual choice for 3D views.", ch: "3.4" },
    "physics-engine": { term: "Physics engine", aka: ["physics","Chaos","PhysX","Jolt"], def: "The engine system that moves objects under forces such as gravity, and detects and resolves collisions between them.", ch: "2.1" },
    "physics-interpolation": { term: "Physics interpolation", aka: ["interpolation","Rigidbody interpolation"], def: "Drawing each moving object part-way between its last two physics steps, according to how far the current frame lies between them, so motion stays smooth when physics and rendering run at different rates.", ch: "2.2" },
    "pipeline-stage": { term: "Pipeline stage", aka: ["stage"], def: "One step of the graphics pipeline, with a fixed input and output. All stages work at the same time on different triangles and pixels, so the slowest one sets the pace.", ch: "5.1" },
    "pipelining": { term: "Pipelining", aka: ["frame pipelining","parallel rendering"], def: "Working on several frames at once in different stages, like an assembly line: the game thread updates one frame while the render thread prepares the one before and the GPU draws the one before that.", ch: "2.2" },
    "pixel": { term: "Pixel", aka: [], def: "One dot of the final image. A 1920 by 1080 frame has about 2.07 million of them.", ch: "3.1" },
    "pixel-coverage": { term: "Pixel coverage", aka: ["coverage","coverage test","inside test"], def: "Whether a triangle covers a pixel, decided by testing the pixel's sample point against the triangle's three edges. A pixel is either fully in or fully out.", ch: "5.3" },
    "pixel-quad": { term: "Pixel quad", aka: ["2×2 quad","quad","helper lane","helper pixel","helper invocation"], def: "A 2 by 2 block of pixels that the GPU always shades together, so the shader can compare neighbours. Pixels in the block that the triangle does not cover still run, as helper lanes, and their results are thrown away.", ch: "5.4" },
    "pixel-shader": { term: "Pixel shader", aka: ["fragment shader"], def: "The GPU program that runs for every pixel a triangle covers and decides that pixel's colour.", ch: "5.4" },
    "platform": { term: "Platform", aka: ["target platform","target"], def: "Everything a game runs on and sells through: the hardware, its operating system, its store and its owner's rules. PS5, Windows PCs, Android phones and web browsers are platforms.", ch: "1.4" },
    "platform-holder": { term: "Platform holder", aka: ["platform owner","first party","console manufacturer"], def: "The company that controls a closed platform and its store, such as Sony, Microsoft, Nintendo or Meta, and decides which games may be sold on it.", ch: "1.4" },
    "platform-layer": { term: "Platform layer", aka: ["platform abstraction layer","HAL","OS layer"], def: "The bottom layer of an engine that wraps each operating system's way of opening windows, reading controllers, accessing files, keeping time and starting threads, so the rest of the engine does not care which platform it runs on.", ch: "2.1" },
    "plugin": { term: "Plugin", aka: ["module","package","addon","extension","GDExtension"], def: "A self-contained bundle of code and content that adds a feature to an engine without changing the engine itself. Engines split their own code into modules the same way, so features can be included or left out of each build.", ch: "2.1" },
    "point": { term: "Point", aka: ["position","location"], def: "A place, measured from an origin. Subtracting one point from another gives the vector between them, and adding a vector to a point moves it; adding two points together means nothing.", ch: "3.3" },
    "polygon-count": { term: "Polygon count", aka: ["poly count","polycount","triangle count","tri count"], def: "How many triangles a mesh or a whole frame contains. Teams set budgets per asset and per frame for each platform, because every triangle costs vertex work, memory and shading efficiency.", ch: "4.1" },
    "pom": { term: "Parallax occlusion mapping", aka: ["POM","Deep Parallax","pixel displacement"], def: "Stepping along the view ray through a height map in every pixel until it meets the surface, so raised detail shifts with the view and hides what is behind it. Costs several to dozens of texture reads per pixel.", ch: "6.4" },
    "power-budget": { term: "Power budget", aka: ["thermal budget","TDP"], def: "How much electrical power a device can draw and how much heat it can shed. It limits sustained performance far more tightly on phones and headsets than on consoles and PCs.", ch: "1.4" },
    "pre-production": { term: "Pre-production", aka: ["preproduction"], def: "The phase after concept where a small team tests the riskiest ideas, proves the look and the pipeline, sets budgets and plans the rest of the project. It usually ends with a vertical slice.", ch: "1.1" },
    "prefab": { term: "Prefab", aka: ["Blueprint class","packed scene","template"], def: "A saved, reusable object with its components and children that can be placed many times. Editing the prefab updates every placed copy.", ch: "2.3" },
    "prefab-instance": { term: "Prefab instance", aka: ["instance","instanced scene"], def: "One placed copy of a prefab. It stays linked to the prefab, so it picks up changes made to it.", ch: "2.3" },
    "prefab-variant": { term: "Prefab variant", aka: ["inherited scene","child Blueprint"], def: "A prefab based on another prefab that changes some of its values and inherits the rest, such as a mossy crate made from the plain one.", ch: "2.3" },
    "premultiplied-alpha": { term: "Premultiplied alpha", aka: ["premultiply","AlphaComposite","associated alpha"], def: "Storing colour already multiplied by its alpha, and blending with new + (1 − alpha) × old. It filters without dark or bright halos and lets one blend mode act as either normal or additive blending.", ch: "5.5" },
    "present": { term: "Present", aka: ["Present()","vkQueuePresentKHR","flip","swap"], def: "The call that hands a finished frame to the display system, moving it to the front of the swap chain at the next allowed moment.", ch: "3.1" },
    "primitive-assembly": { term: "Primitive assembly", aka: ["triangle assembly","clipping and culling"], def: "The fixed step after the vertex shader that joins shaded corners into triangles, drops triangles facing away from the camera, and clips away what lies outside the view.", ch: "5.1" },
    "producer": { term: "Producer", aka: ["project manager"], def: "The person who plans and tracks the work: schedule, scope, priorities and who does what next. The creative and technical decisions inside the plan belong to the leads.", ch: "1.2" },
    "production": { term: "Production", aka: ["full production"], def: "The main phase of development, when the full team builds the game's features and content to the plan and budgets set in pre-production.", ch: "1.1" },
    "profiler": { term: "Frame capture tool", aka: ["profiler","RenderDoc","PIX on Windows"], def: "A tool that records one frame so you can inspect every draw call, buffer and texture, and how long each pass took.", ch: "11.5" },
    "programmable-stage": { term: "Programmable stage", aka: ["shader stage"], def: "A pipeline stage that runs a shader written for the game, such as the vertex shader or the pixel shader.", ch: "5.1" },
    "projection-matrix": { term: "Projection matrix", aka: ["P","camera projection"], def: "The matrix that takes view-space positions into clip space. It holds the field of view, aspect ratio and near and far planes, and makes the view perspective or orthographic.", ch: "3.4" },
    "prototype": { term: "Prototype", aka: [], def: "A quick, disposable build made to answer one question, such as whether a mechanic is fun or whether an effect can run on the target hardware.", ch: "1.1" },
    "pso": { term: "Pipeline state object", aka: ["PSO","pipeline","graphics pipeline"], def: "A bundle of compiled shaders plus the fixed GPU settings they run with, such as vertex layout, blend, depth and stencil state and target formats. Modern APIs need one for each combination a draw uses, created in advance.", ch: "5.6" },
    "pso-cache": { term: "PSO cache", aka: ["pipeline cache","PSO precaching","shader warm-up","prewarming","bundled PSO cache"], def: "Ways of creating pipeline state objects before they are needed and keeping the results on disk, so later runs and later draws do not stall on compilation.", ch: "5.6" },
    "qa": { term: "QA", aka: ["quality assurance","tester","QA tester"], def: "Quality assurance: the people who test every build, find and report bugs, check fixes and confirm the game works on each target platform.", ch: "1.2" },
    "quad": { term: "Quad", aka: ["quadrilateral","quad modelling","quad topology"], def: "A four-sided face. Artists model mostly in quads because they form clean rows of edges that are easy to select, edit and subdivide; each becomes two triangles on export.", ch: "4.1" },
    "quad-overdraw": { term: "Quad overdraw", aka: ["quad overshading","Quad Overdraw view"], def: "Extra pixel shader runs caused by 2 by 2 quads that triangles only partly cover, especially along shared edges and on small or thin triangles.", ch: "5.4" },
    "quantization": { term: "Vertex quantization", aka: ["vertex compression","mesh compression","packing"], def: "Storing vertex attributes with fewer bits, for example 16-bit instead of 32-bit numbers, to save memory and bandwidth at a small loss of precision.", ch: "4.2" },
    "raci": { term: "RACI", aka: ["RACI matrix","RACI chart","responsibility assignment matrix"], def: "A grid of decisions or tasks against people that marks who is Responsible for doing the work, Accountable for the result, Consulted before and Informed after. Each row should have exactly one Accountable person.", ch: "1.2" },
    "rasterization": { term: "Rasterization", aka: ["rasterisation","scan conversion"], def: "The fixed GPU step that finds which pixels a triangle covers and gives each of them a blend of the values at the triangle's three corners.", ch: "5.3" },
    "rasterizer": { term: "Rasterizer", aka: ["rasterizer stage","raster stage"], def: "The fixed GPU stage that finds which pixels each triangle covers and hands each one to the pixel shader with values blended from the triangle's three corners.", ch: "5.1" },
    "ray-marching": { term: "Ray marching", aka: ["screen-space tracing"], def: "Following a ray in small steps and checking at each step whether it has gone behind a surface, often using the depth buffer.", ch: "8.4" },
    "ray-tracing": { term: "Ray tracing", aka: ["RT","hardware ray tracing"], def: "Finding what a ray hits by testing it against the actual scene geometry, using acceleration structures that GPUs can now traverse in hardware.", ch: "8.6" },
    "real-time-rendering": { term: "Real-time rendering", aka: ["real-time graphics","interactive rendering"], def: "Drawing images fast enough to keep up with the player, typically 30 to well over 100 images a second. Offline rendering for film can instead spend minutes or hours on a single image.", ch: "0.1" },
    "recommended-spec": { term: "Recommended specification", aka: ["recommended requirements","rec spec"], def: "The hardware a PC game suggests for the experience its makers intend, often given with a resolution, frame rate and settings preset.", ch: "1.4" },
    "refresh-rate": { term: "Refresh rate", aka: ["Hz","hertz","refresh"], def: "How many times per second a display redraws its picture, in hertz (Hz). A 60 Hz display starts a new picture every 16.7 ms; a 144 Hz display every 6.9 ms.", ch: "3.1" },
    "render-pass": { term: "Render pass", aka: ["pass"], def: "One step in drawing a frame that reads some images and writes others, such as the shadow pass, the AO pass or the lighting pass.", ch: "5.6" },
    "render-pipeline": { term: "Render pipeline", aka: ["Scriptable Render Pipeline","SRP","rendering pipeline"], def: "The part of an engine that decides how each frame is drawn: which passes run, in what order and with which lighting. In Unity it is a swappable package, URP or HDRP.", ch: "2.4" },
    "render-target": { term: "Render target", aka: ["RT","colour attachment","render texture","framebuffer attachment"], def: "An image the GPU draws into instead of, or before, the screen, such as a shadow map, a G-buffer layer or an HDR colour buffer. Later passes read it as a texture.", ch: "5.6" },
    "render-thread": { term: "Render thread", aka: ["rendering thread","RenderThread"], def: "A CPU thread that takes a copy of what the game thread produced and turns it into work for the GPU, while the game thread is already updating the next frame.", ch: "2.2" },
    "renderer": { term: "Renderer", aka: ["rendering engine","render pipeline","rendering server"], def: "The part of an engine that turns the current state of the game world into an image each frame. It decides what is visible, organises the drawing into passes and sends the work to the GPU.", ch: "2.1" },
    "rendering-method": { term: "Rendering method", aka: ["Godot renderer","Mobile renderer","Compatibility renderer"], def: "Godot's choice of renderer for a project: Forward+ for desktop, Mobile for phones and standalone VR, or Compatibility for older hardware and the web.", ch: "2.4" },
    "resolution": { term: "Resolution", aka: ["output resolution","display resolution","1080p","1440p","4K"], def: "The number of pixels in an image, written width × height. 1920 × 1080 (1080p) is about 2.07 million pixels; 3840 × 2160 (4K) is four times as many.", ch: "3.1" },
    "retopology": { term: "Retopology", aka: ["retopo","remeshing"], def: "Building a new, lighter mesh over a detailed sculpt, with edges placed where the shape and animation need them, so the model is cheap enough for a game.", ch: "1.3" },
    "reversed-z": { term: "Reversed-Z", aka: ["reverse Z","reversed depth","inverted depth buffer"], def: "Storing depth with the near plane at 1 and the far distance at 0, in a 32-bit floating-point depth buffer. It makes depth precision almost even across the view and greatly reduces z-fighting, at no cost.", ch: "5.5" },
    "rgb": { term: "RGB", aka: ["red, green, blue","RGB colour"], def: "Describing a colour as three amounts of light: red, green and blue. Every pixel on a screen mixes those three lights to make the colours it can show.", ch: "3.2" },
    "rhi": { term: "RHI", aka: ["render hardware interface","Rendering Hardware Interface","RenderingDevice","graphics abstraction layer"], def: "The layer that gives the renderer one set of graphics commands and translates them into whichever graphics API the platform uses, such as DirectX 12, Vulkan or Metal.", ch: "2.1" },
    "rhi-thread": { term: "RHI thread", aka: ["RHIT","RHIThread"], def: "In Unreal Engine, a third CPU thread that translates the render thread's platform-neutral command lists into DirectX 12, Vulkan or Metal calls and hands them to the GPU.", ch: "2.2" },
    "royalty": { term: "Royalty", aka: ["revenue share"], def: "A percentage of a game's revenue paid to the engine maker. Unreal Engine charges one on a game's gross revenue above its first $1 million.", ch: "2.4" },
    "rtao": { term: "RTAO", aka: ["ray-traced ambient occlusion"], def: "Ambient occlusion computed by tracing short rays against the real scene geometry instead of reading the depth buffer, so it sees hidden and off-screen objects.", ch: "8.3" },
    "runtime": { term: "Runtime", aka: ["player","game build","shipping build"], def: "The part of an engine that ships inside the game and runs on players' machines. It contains the systems that run each frame, without the editor's tools.", ch: "2.1" },
    "sample-point": { term: "Sample point", aka: ["pixel centre","pixel center","sample location"], def: "The single point at which the GPU tests whether a triangle covers a pixel. Without multisampling it is the pixel's centre, half a pixel in from its top-left corner.", ch: "5.3" },
    "scalability": { term: "Scalability", aka: ["quality settings","quality levels","presets","scalability settings"], def: "The settings that let one game trade visual quality for speed and memory, grouped into presets for each platform and device tier.", ch: "1.4" },
    "scan-out": { term: "Scan-out", aka: ["scanout","raster scan"], def: "The display reading its picture out of the front buffer row by row, from the top of the screen to the bottom, during each refresh.", ch: "3.1" },
    "scene": { term: "Scene", aka: ["level","map","scene file",".umap",".unity",".tscn"], def: "One saved world or piece of a world, such as a level, a menu or a test room, holding every object placed in it. Unreal Engine calls it a level or map.", ch: "2.3" },
    "scene-graph": { term: "Scene graph", aka: ["scene hierarchy","hierarchy","scene tree","Outliner"], def: "The tree of every object in a scene, where each object can have children that move with it. Editors show it as the Hierarchy, the Outliner or the Scene dock.", ch: "2.3" },
    "screen-space": { term: "Screen space", aka: ["image space"], def: "Working from the rendered image and its depth rather than the 3D scene. Screen-space techniques are fast, but they only know about what the camera currently sees.", ch: "3.4" },
    "screen-space-derivatives": { term: "Screen-space derivatives", aka: ["derivatives","ddx","ddy","dFdx","dFdy","fwidth"], def: "How fast a value changes from one pixel to the next, measured by comparing neighbours in a 2 by 2 quad. Texture sampling uses them to pick the right mip level.", ch: "5.4" },
    "screen-tearing": { term: "Screen tearing", aka: ["tearing","tear line"], def: "A horizontal break across the picture where the rows above show one frame and the rows below show the next, because the frame was swapped while the display was still reading the screen out.", ch: "3.1" },
    "scripting-layer": { term: "Scripting layer", aka: ["scripting","gameplay scripting","Blueprints","GDScript","C# scripts"], def: "The language and interface gameplay programmers and designers use to write a game's logic on top of the engine, such as Blueprints, C# in Unity or GDScript in Godot.", ch: "2.1" },
    "seat-licence": { term: "Seat licence", aka: ["per-seat subscription","seat"], def: "A licence paid for each person who uses the editor, usually yearly, whatever the game earns. Unity charges this way once a company passes its free tier.", ch: "2.4" },
    "shader": { term: "Shader", aka: ["shader program"], def: "A small program that runs on the GPU for every vertex, pixel or work item, in parallel.", ch: "5.1" },
    "shader-compilation": { term: "Shader compilation", aka: ["shader compile","shader compiling"], def: "Turning shader source into GPU machine code in two stages: into an in-between form such as DXIL or SPIR-V when the game is built, then into the player's exact GPU's code by the driver. The second stage causes hitches if it happens during play.", ch: "3.5" },
    "shader-complexity-view": { term: "Shader complexity view", aka: ["Shader Complexity","overdraw view","Display Overdraw"], def: "An engine debug view that colours each pixel by how much shading it costs, from cheap to expensive, so overlapping or heavy materials stand out.", ch: "5.4" },
    "shader-graph": { term: "Shader graph", aka: ["Material Editor","Shader Graph","Visual Shader","node-based shader editor"], def: "A node-based editor where artists build shaders by wiring boxes together. The engine turns the graph into ordinary shader code and compiles it like any other shader.", ch: "5.6" },
    "shader-stutter": { term: "Shader compilation stutter", aka: ["PSO stutter","shader hitch","compile hitch","first-use hitch"], def: "A hitch the first time something is drawn, because its pipeline state object is created and its shaders compiled by the driver at that moment instead of during loading.", ch: "5.6" },
    "shader-variant": { term: "Shader variant", aka: ["shader permutation","keyword variant","static switch"], def: "One compiled version of a shader for one combination of on/off features. Each independent toggle doubles the count, so five toggles make 32 variants before passes and platforms multiply them again.", ch: "5.6" },
    "simd": { term: "SIMD and SIMT", aka: ["SIMD","SIMT","single instruction, multiple data","single instruction, multiple threads"], def: "Running many lanes from one stream of instructions: the hardware issues each instruction once and every lane in a group applies it to its own data. SIMT is NVIDIA's name for the version where each lane looks like its own thread.", ch: "3.5" },
    "sky-light": { term: "Sky light", aka: ["ambient light","environment light"], def: "Light arriving from the whole surrounding environment rather than one point, such as the blue sky on a sunny day or a uniform grey overcast.", ch: "7.1" },
    "slice": { term: "Slice", aka: ["slice direction"], def: "In GTAO, one direction across the screen through a pixel. The pixel's hemisphere is examined one thin vertical slice at a time.", ch: "8.3" },
    "small-triangle-cost": { term: "Small-triangle cost", aka: ["micro-triangles","micropolygons","tiny triangles"], def: "The extra GPU work caused by triangles only a few pixels in size: each still needs setup and shades whole 2 by 2 pixel quads, so up to three quarters of the shading is thrown away.", ch: "5.3" },
    "source-asset": { term: "Source asset", aka: ["source file","source art","working file"], def: "The editable original of a piece of content, such as a sculpt or a layered texture project. The team keeps and versions it; players never receive it.", ch: "1.3" },
    "source-available": { term: "Source-available", aka: ["source access","engine source"], def: "Source code you may read and change under the vendor's licence, but not share or reuse freely. Unreal Engine's full source is available this way.", ch: "2.4" },
    "sparse-texture": { term: "Sparse texture", aka: ["tiled resources","sparse residency","reserved resources","partially resident texture"], def: "A texture with only some of its memory pages backed by real memory, using the GPU's own memory mapping. It is the hardware support behind some virtual texturing systems.", ch: "6.3" },
    "specular": { term: "Specular reflection", aka: ["specular","highlights"], def: "Light reflected in a preferred direction, like a mirror or a highlight on polished metal. It changes as the viewer moves.", ch: "7.2" },
    "specular-occlusion": { term: "Specular occlusion", aka: ["GTSO","ground-truth specular occlusion"], def: "Darkening reflections in creases and cavities where the reflected direction is blocked by nearby geometry.", ch: "8.3" },
    "spir-v": { term: "SPIR-V", aka: ["SPIRV"], def: "A standard intermediate format for compiled shaders, defined by the Khronos Group. Vulkan drivers read it, and tools translate between it and HLSL, GLSL and Metal's language.", ch: "5.6" },
    "split-vertex": { term: "Split vertex", aka: ["seam","hard edge","duplicated vertex"], def: "A corner stored as two or more vertices at the same position because the triangles meeting there need different normals, UVs or colours.", ch: "4.2" },
    "srgb": { term: "sRGB", aka: ["sRGB transfer function","sRGB gamut","Rec. 709 primaries","IEC 61966-2-1"], def: "The standard colour space for PC screens and the web. It fixes which red, green and blue the screen uses, and a curve that stores values so that 8 bits are spent where eyes notice differences.", ch: "3.2" },
    "ssao": { term: "SSAO", aka: ["screen-space ambient occlusion"], def: "Ambient occlusion estimated from the depth buffer by testing a handful of nearby sample points per pixel. Fast, noisy, and limited to what is on screen.", ch: "8.3" },
    "ssgi": { term: "SSGI", aka: ["screen-space global illumination","SSIL","screen-space indirect lighting"], def: "Bounced light estimated by tracing rays through the depth buffer and picking up colour from the lit image. It inherits every screen-space blind spot.", ch: "8.4" },
    "ssr": { term: "SSR", aka: ["screen-space reflections"], def: "Reflections found by tracing rays through the depth buffer and reusing the colour of whatever on-screen pixel they hit.", ch: "7.6" },
    "static-buffer": { term: "Static buffer", aka: ["static vertex buffer","immutable buffer"], def: "A GPU buffer filled once, usually at load time, and then only read. Most level geometry and props use static buffers.", ch: "4.2" },
    "stencil-buffer": { term: "Stencil buffer", aka: ["stencil","custom stencil"], def: "A screen-sized buffer holding a small whole number per pixel, usually 8 bits, stored alongside depth. Draws write marks into it and later draws test against them, for outlines, portals and masks.", ch: "5.5" },
    "stencil-test": { term: "Stencil test", aka: ["stencil compare"], def: "The per-pixel comparison between a draw's reference value and the number stored in the stencil buffer, with rules for how the stored number changes when the test passes or fails.", ch: "5.5" },
    "streaming-pool": { term: "Texture streaming pool", aka: ["texture pool","streaming pool","pool size","r.Streaming.PoolSize"], def: "The fixed amount of GPU memory a texture streamer may fill. When the mips the camera wants do not fit, it drops the sharpest levels, so textures look soft.", ch: "6.3" },
    "stride": { term: "Stride", aka: ["vertex size"], def: "The number of bytes from the start of one vertex to the start of the next in a buffer. It is the size of one row.", ch: "4.2" },
    "swap-chain": { term: "Swap chain", aka: ["swapchain","flip chain"], def: "The set of framebuffers, usually two or three, that the graphics API passes in turn between the GPU and the display, together with the rules for when they swap.", ch: "3.1" },
    "taa": { term: "TAA", aka: ["temporal anti-aliasing"], def: "Anti-aliasing that jitters the camera slightly every frame and blends each new frame with the reprojected previous ones.", ch: "9.2" },
    "tangent": { term: "Tangent", aka: ["tangent vector","tangent frame"], def: "A direction lying along a surface, aligned with its texture's horizontal axis. Normal maps need it to know which way is which.", ch: "4.1" },
    "tangent-space": { term: "Tangent space", aka: ["TBN","tangent basis","texture space"], def: "A frame of reference sitting on the surface at each point, made of the normal, the tangent and the bitangent. Normal maps are usually written in it, so they work on any shape, tile and bend with animation.", ch: "6.4" },
    "technical-artist": { term: "Technical artist", aka: ["TA","tech artist"], def: "A specialist who works between art and programming. Technical artists build materials, shaders, tools and import rules, and make sure art looks right in the engine and stays within its performance budgets.", ch: "1.2" },
    "temporal-accumulation": { term: "Temporal accumulation", aka: ["history","temporal filter","temporal reprojection"], def: "Spreading work over several frames: each frame computes a few new samples and blends them with the result from previous frames, moved to account for motion.", ch: "9.2" },
    "tessellation": { term: "Tessellation", aka: ["hardware tessellation","Nanite Tessellation","subdivision"], def: "Splitting triangles into many smaller ones on the GPU at draw time, usually more finely near the camera, so that displacement has vertices to move.", ch: "6.4" },
    "texture": { term: "Texture", aka: ["map"], def: "An image the GPU reads while shading, such as a colour, normal or roughness map. Also used to store data like depth or AO.", ch: "6.1" },
    "texture-budget": { term: "Texture memory budget", aka: ["texture budget","Memory Budget","VRAM budget"], def: "The share of the weakest target's memory that a game's textures may use, after render targets, geometry and everything else. Texture sizes, formats and streaming are tuned to fit it.", ch: "6.3" },
    "texture-streaming": { term: "Texture streaming", aka: ["texture streamer","streaming"], def: "Loading and unloading parts of textures while the game runs, so memory holds only the detail the camera currently needs and the rest stays on disk.", ch: "6.3" },
    "thermal-throttling": { term: "Thermal throttling", aka: ["throttling","thermal limiting"], def: "A device lowering its chips' clock speeds when it gets too hot, which makes a game slow down partway through a session.", ch: "1.4" },
    "thickness-heuristic": { term: "Thickness heuristic", aka: ["thickness"], def: "A guess that surfaces in the depth buffer are only so thick, so geometry behind them is treated as open. It reduces dark halos around thin foreground objects.", ch: "8.3" },
    "thread-group": { term: "Thread group", aka: ["workgroup","work group","numthreads","dispatch"], def: "A block of compute shader threads, such as 8 × 8, that run together on one compute unit and can share fast memory. A dispatch launches a grid of thread groups.", ch: "5.6" },
    "tick": { term: "Update", aka: ["tick","Tick()","Update()","_process()"], def: "The step in each frame where the engine moves the game forward by the time that has passed: it reads input, runs gameplay code and updates every object that needs it.", ch: "2.2" },
    "tile-based-gpu": { term: "Tile-based GPU", aka: ["tile-based rendering","TBR","tile-based deferred rendering","TBDR","tiler"], def: "A GPU that sorts a pass's triangles into small screen tiles, then renders each tile in fast on-chip memory and writes it out once. Phone GPUs work this way to save memory traffic, power and heat.", ch: "3.5" },
    "tools-programmer": { term: "Tools programmer", aka: ["tools engineer","pipeline programmer"], def: "A programmer who builds the editors, importers, build systems and automation that the rest of the team uses to make the game.", ch: "1.2" },
    "topology": { term: "Topology", aka: ["mesh topology","edge flow","edge loops"], def: "How a mesh's corners, edges and faces connect to each other, whatever their exact positions. Clean topology is easy to edit, unwrap and reduce, and deforms well when animated.", ch: "4.1" },
    "transform": { term: "Transform", aka: ["position, rotation and scale","TRS"], def: "An object's position, rotation and scale. Every object placed in a game world has one.", ch: "2.3" },
    "transform-hierarchy": { term: "Transform hierarchy", aka: ["parent-child","parenting","attachment"], def: "Parent and child links between objects, so that moving, turning or scaling a parent does the same to all of its children.", ch: "2.3" },
    "transparency-sorting": { term: "Transparency sorting", aka: ["sort order","translucency sort","back-to-front sorting","sort priority"], def: "Drawing transparent objects after all opaque ones, ordered from the furthest to the nearest, usually by the distance to each object's centre. It fails for large or intersecting transparent objects.", ch: "5.5" },
    "triangle": { term: "Triangle", aka: ["polygon","face","primitive"], def: "The basic shape GPUs draw. Three corners always lie on one flat plane, which makes triangles fast and unambiguous to fill.", ch: "4.1" },
    "triangle-list": { term: "Triangle list", aka: ["primitive topology"], def: "The most common way to read indices: every three indices form one independent triangle.", ch: "4.2" },
    "triangulation": { term: "Triangulation", aka: ["triangulate","triangulated"], def: "Splitting quads and n-gons into triangles, on export, on import or in the engine. Doing it once, at a known point, keeps the triangles identical in every tool.", ch: "4.1" },
    "triple-buffering": { term: "Triple buffering", aka: ["three-buffer swap chain"], def: "Using three framebuffers so the GPU can start the next frame while a finished one waits for the display. It keeps the GPU busy under vsync at the cost of up to one more frame of delay.", ch: "3.1" },
    "ubershader": { term: "Ubershader", aka: ["uber shader","mega shader"], def: "One large shader that handles many features with branches instead of separate compiled variants. It needs fewer compiles but usually runs slower than a specialised variant.", ch: "5.6" },
    "uncompressed-format": { term: "Uncompressed format", aka: ["RGBA8","RGBA32","R8G8B8A8","RGBA16F"], def: "A texture format that stores every texel in full, such as RGBA8 at 4 bytes per texel. Exact, but four to eight times larger than block-compressed formats.", ch: "6.3" },
    "unified-memory": { term: "Unified memory", aka: ["shared memory","UMA"], def: "One pool of memory shared by the CPU and GPU, as on consoles, phones and headsets, instead of separate system RAM and VRAM as on most PCs.", ch: "1.4" },
    "unit-vector": { term: "Unit vector", aka: ["normalised vector","normalized vector","normalise","normalize","direction"], def: "A vector with a length of exactly 1, so it carries only a direction. Normalising a vector divides it by its own length to make it one.", ch: "3.3" },
    "unity": { term: "Unity", aka: ["Unity 6","Unity engine"], def: "Unity Technologies' engine, scripted in C#, with two current render pipelines, URP and HDRP. It is licensed per seat and free for small companies.", ch: "2.4" },
    "unreal-engine": { term: "Unreal Engine", aka: ["UE5","UE","Unreal"], def: "Epic Games' engine, written in C++ with Blueprint visual scripting. Its fifth version brought features such as Nanite geometry and Lumen lighting, and it charges games a royalty on revenue above $1 million.", ch: "2.4" },
    "up-axis": { term: "Up axis", aka: ["Y-up","Z-up","vertical axis"], def: "The axis a coordinate system treats as vertical. Unity, Godot and glTF use Y; Unreal Engine, Blender and 3ds Max use Z.", ch: "3.4" },
    "urp": { term: "URP", aka: ["Universal Render Pipeline"], def: "Unity's render pipeline for every platform Unity supports, tuned for mobile GPUs and standalone VR. Unity recommends it for new projects.", ch: "2.4" },
    "usd": { term: "USD", aka: ["OpenUSD","Universal Scene Description",".usda",".usdc",".usdz"], def: "Pixar's open-source scene description format, built for assembling large scenes from many files. Layers, references and variants let teams change a scene without editing the original files.", ch: "1.3" },
    "uv": { term: "UV coordinates", aka: ["UVs","texture coordinates","texcoords"], def: "Two numbers per vertex saying which point of a 2D texture lands on that corner of the 3D surface.", ch: "4.1" },
    "uv-seam": { term: "UV seam", aka: ["seam","texture seam","UV cut"], def: "An edge where the UV layout is cut so the surface can lie flat in the texture. The triangles on either side land in different places in the texture, so vertices along the seam are stored twice.", ch: "4.1" },
    "variable-hardware": { term: "Variable hardware", aka: ["open platform","hardware fragmentation"], def: "A platform where players own very different machines, such as PCs and Android phones, so a game must adapt its settings to each one.", ch: "1.4" },
    "vector": { term: "Vector", aka: ["direction vector","displacement","float3","Vector3","FVector"], def: "An arrow written as a list of numbers, one per axis: (3, 2) means 3 along x and 2 along y. It has a direction and a length but no fixed place, so games use it for movement, velocity and facing.", ch: "3.3" },
    "version-control": { term: "Version control", aka: ["source control","revision control","VCS"], def: "A system that keeps every revision of every file, records who changed what and when, and lets a team return to any earlier state.", ch: "1.3" },
    "vertex": { term: "Vertex", aka: ["vertices","vert"], def: "One corner of a mesh together with everything stored about it: position, normal, UVs and more.", ch: "4.1" },
    "vertex-animation": { term: "Vertex animation", aka: ["vertex shader animation","World Position Offset","WPO","vertex offset","vertex displacement"], def: "Moving a mesh's vertices in the vertex shader every frame, for effects such as foliage swaying in the wind or a flag rippling, with no skeleton and no work on the CPU.", ch: "5.2" },
    "vertex-attribute": { term: "Vertex attribute", aka: ["attribute","vertex channel","vertex element"], def: "One piece of data stored per vertex, such as position, normal, UV, colour or bone weights.", ch: "4.2" },
    "vertex-buffer": { term: "Vertex buffer", aka: ["VBO","vertex array"], def: "A block of GPU memory holding a mesh's vertices as rows of numbers, one row per vertex, ready for the GPU to read.", ch: "4.2" },
    "vertex-cache": { term: "Post-transform vertex cache", aka: ["vertex cache","post-transform cache"], def: "A small GPU cache of recently processed vertices. When an index repeats soon after, the GPU reuses the result instead of running the vertex shader again.", ch: "4.2" },
    "vertex-colour": { term: "Vertex colour", aka: ["vertex color","vertex paint","COLOR_0"], def: "A colour, or four numbers, stored at each vertex and blended across the triangles between. Games use it as a cheap mask for dirt, material blending, wind strength and similar effects.", ch: "4.1" },
    "vertex-layout": { term: "Vertex layout", aka: ["input layout","vertex declaration","vertex format","vertex descriptor"], def: "The description that tells the GPU how to read a vertex buffer: which attributes it holds, their formats, and their byte offsets inside each row.", ch: "4.2" },
    "vertex-shader": { term: "Vertex shader", aka: [], def: "The GPU program that runs once per vertex, typically to move it from the model's own coordinates to its place on screen.", ch: "5.2" },
    "vertex-stream": { term: "Vertex stream", aka: ["separate streams","structure of arrays","SoA"], def: "One of several vertex buffers that together describe a mesh, each holding some of the attributes, such as positions in one buffer and everything else in another.", ch: "4.2" },
    "vertical-blank": { term: "Vertical blank", aka: ["vblank","vertical blanking interval","VBI"], def: "The short pause after a display has drawn its bottom row and before it starts again at the top. Swapping frames during it causes no tearing.", ch: "3.1" },
    "vertical-slice": { term: "Vertical slice", aka: ["slice"], def: "A small part of a game, such as one level, built to final quality in every layer and running on the target hardware. It proves the game and gives the cost of building the rest.", ch: "1.1" },
    "vfx-artist": { term: "VFX artist", aka: ["effects artist","FX artist"], def: "An artist who creates visual effects such as fire, smoke, magic, impacts and weather, usually with particle systems and custom materials.", ch: "1.2" },
    "view-matrix": { term: "View matrix", aka: ["camera matrix","world-to-view matrix","world-to-camera matrix","V"], def: "The matrix that moves the whole world into view space so the camera sits at the origin. It is the inverse of the camera's own transform.", ch: "3.4" },
    "view-space": { term: "View space", aka: ["camera space","eye space"], def: "Coordinates measured from the camera: the camera sits at the origin and looks straight along one axis. Some lighting and depth calculations are done here.", ch: "3.4" },
    "virtual-texturing": { term: "Virtual texturing", aka: ["SVT","streaming virtual texturing","runtime virtual texturing","megatexture"], def: "Cutting textures into small pages and loading only the pages visible pixels use into a fixed cache, with a page table telling the shader where each page is. Memory stays nearly constant however large the textures are.", ch: "6.3" },
    "vr-reprojection": { term: "Reprojection (VR)", aka: ["reprojection","TimeWarp","SpaceWarp","Application SpaceWarp","AppSW"], def: "A headset reusing or synthesising frames when the game's frame is late or deliberately rendered at half rate, warping images to the latest head position so the world stays steady.", ch: "1.4" },
    "vram": { term: "VRAM", aka: ["video RAM","video memory","GPU memory"], def: "The GPU's own memory. Meshes and textures live here so the GPU can read them fast without asking the CPU.", ch: "3.5" },
    "vrr": { term: "Variable refresh rate", aka: ["VRR","G-SYNC","FreeSync","Adaptive-Sync","HDMI VRR"], def: "A display mode in which the screen waits for each new frame and refreshes when it arrives, within a range such as 48 to 144 Hz. It removes tearing without the stutter of vsync.", ch: "3.1" },
    "vsync": { term: "Vsync", aka: ["V-Sync","vertical sync","vertical synchronisation"], def: "Holding each finished frame until the display's vertical blank before swapping it in. It removes tearing but adds waiting, and uneven waits show as stutter.", ch: "3.1" },
    "vulkan": { term: "Vulkan", aka: [], def: "The Khronos Group's cross-platform explicit graphics API. It is the main API on Android and Linux, including the Steam Deck, and also runs on Windows and Nintendo Switch.", ch: "3.5" },
    "warp": { term: "Warp", aka: ["wavefront","wave","subgroup","SIMD-group"], def: "A group of GPU lanes that run the same instruction together: 32 lanes on NVIDIA GPUs, 32 or 64 on AMD's. When lanes in one warp take different branches, the warp runs both.", ch: "3.5" },
    "webgpu": { term: "WebGPU", aka: [], def: "The modern graphics API for web browsers and the successor to WebGL. Chrome, Edge, Firefox and Safari ship it, though not yet on every operating system.", ch: "3.5" },
    "winding-order": { term: "Winding order", aka: ["front face","CW","clockwise","CCW","counter-clockwise"], def: "Whether a triangle's corners go clockwise or anticlockwise on screen. The GPU uses it to decide which side of the triangle is the front.", ch: "4.1" },
    "world-space": { term: "World space", aka: ["global space","scene space"], def: "The single coordinate space shared by the whole level, in which every object, light and camera has a position.", ch: "3.4" },
    "world-transform": { term: "World transform", aka: ["global transform","global_position","world location"], def: "An object's position, rotation and scale measured from the world's origin, found by combining its local transform with every parent above it.", ch: "2.3" },
    "z-fighting": { term: "Z-fighting", aka: ["depth fighting","z-fight"], def: "Flickering stripes where two surfaces closer together than one step of stored depth show through each other, because rounding rather than distance decides which is in front.", ch: "5.5" }
  };
})();
